import assert from 'node:assert/strict';import {mkdtemp,mkdir,writeFile,readFile,rm} from 'node:fs/promises';import {tmpdir} from 'node:os';import {join} from 'node:path';import {createHash} from 'node:crypto';import {spawnSync} from 'node:child_process';import {SUITE_MANIFEST} from '../../lib/suite/index.js';const sri=b=>'sha512-'+createHash('sha512').update(b).digest('base64');
export async function sourceArchives(t){const root=await mkdtemp(join(tmpdir(),'hm-core-managed-source-'));t.after(()=>rm(root,{recursive:true,force:true}));const rows=[{name:SUITE_MANIFEST.core.name,version:SUITE_MANIFEST.core.version,repository:SUITE_MANIFEST.core.repository},...SUITE_MANIFEST.components.map(r=>({name:r.moduleName,version:r.id==='usage'?'0.3.0-rc.4':'0.6.8',repository:r.repository}))];const archives=[];for(const [n,row] of rows.entries()){const dir=join(root,String(n));await mkdir(join(dir,'package'),{recursive:true});await writeFile(join(dir,'package/package.json'),JSON.stringify({...row,fixture:'MANAGED_SOURCE_FIXTURE'}));const path=join(root,n+'.tgz');assert.equal(spawnSync('/usr/bin/tar',['-czf',path,'-C',dir,'package']).status,0);archives.push({path,integrity:sri(await readFile(path))})}return {archives,port:0,peerRegistry:'https://registry.npmjs.org/',maxArchiveBytes:1048576,maxExpandedBytes:2097152,maxEntries:100,maxManifestBytes:65536,maxResponseBytes:1048576,timeoutMs:1000}}
